'use client';

import React, { useCallback, useId } from 'react';
import {
  BarChart as RechartsBarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { useChartAnimation } from './useChartAnimation';
import './Chart.css';
import { readTokenPx } from './palette';
import { useLocale } from '../../behaviors/LocaleProvider';
import { formatAxisNumber, formatNumber } from '../../behaviors/locale';

interface ChartTooltipPayloadEntry {
  value?: number;
  [key: string]: unknown;
}

interface ChartTooltipProps {
  /** The locale the values are written in. */
  locale: string;
  active?: boolean;
  payload?: ChartTooltipPayloadEntry[];
  label?: string | number;
  barColor: string;
  dataLabel: string;
}

export interface ChartSummaryItem {
  /** Label shown above the value */
  label: string;
  /** Formatted value to display */
  value: string | number;
}

/** Props owned by BarChart itself; everything else falls through to the root div. */
type BarChartOwnProps = {
  /** The BCP 47 locale the values, tooltips and value axis are written in, such as `de-DE`. Defaults to the nearest LocaleProvider's, else `en-US`. */
  locale?: string;
  /** Array of data objects */
  data: Record<string, unknown>[];
  /** Key in data for x-axis values */
  xKey?: string;
  /** Key in data for y-axis values */
  yKey?: string;
  /** Display name for the data series (shown in tooltip) */
  dataLabel?: string;
  /**
   * Chart title, in the shared chart header; it also names the figure.
   * Note: this replaces the native `title` tooltip attribute, which the chart does not expose.
   */
  title?: string;
  /** Description text below the title */
  subtitle?: string;
  /** Summary stats displayed in the header */
  summaryItems?: ChartSummaryItem[];
  /** Bar fill colour — CSS value or token reference */
  barColor?: string;
  /** Chart area height in pixels */
  height?: number;
  /** Strip the card chrome (border, padding, fill) when the chart sits inside another panel that supplies the surface */
  bare?: boolean;
  /** Additional CSS classes on the wrapper */
  className?: string;
};

export interface BarChartProps
  extends BarChartOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof BarChartOwnProps | 'children'> {}

/**
 * Reads a CSS custom property from the document root.
 * Falls back to the provided default if unavailable (e.g. SSR).
 */
function getCSSVar(name: string, fallback: string): string {
  // A var() reference resolves live in SVG paint, so the chart follows a
  // theme switch without re-rendering; the fallback covers SSR markup and
  // token-less consumers.
  return `var(${name}, ${fallback})`;
}

/**
 * Custom tooltip rendered inside the chart on hover.
 */
function ChartTooltip({
  locale,
  active,
  payload,
  label,
  barColor,
  dataLabel,
}: ChartTooltipProps) {
  if (!active || !payload?.length) return null;

  return (
    <div className="ds-chart__tooltip">
      <div className="ds-chart__tooltip-label">{label}</div>
      {payload.map((entry, i) => (
        <div key={i} className="ds-chart__tooltip-row">
          <span className="ds-chart__tooltip-dot" style={{ backgroundColor: barColor }} />
          <span className="ds-chart__tooltip-name">{dataLabel}</span>
          <span className="ds-chart__tooltip-value">
            {(entry.value === undefined ? undefined : formatNumber(entry.value, locale))}
          </span>
        </div>
      ))}
    </div>
  );
}

/**
 * Bar chart built on Recharts with design-system tokens.
 * Part of the Chart component family — shares wrapper, header,
 * tooltip, and summary-stat styles with future chart types.
 */
export const BarChart = React.forwardRef<HTMLDivElement, BarChartProps>(({
  data,
  xKey = 'label',
  yKey = 'value',
  dataLabel = 'Value',
  title,
  subtitle,
  summaryItems,
  barColor,
  height = 350,
  bare = false,
  className = '',
  locale: localeProp,
  ...rest
}, ref) => {
  const locale = useLocale(localeProp);
  const formatTick = useCallback(
    (value: unknown) => (typeof value === 'number' ? formatAxisNumber(value, locale) : String(value)),
    [locale],
  );
  const titleId = useId();
  const subtitleId = useId();
  const animation = useChartAnimation(data);
  const baseClass = 'ds-chart';
  const classes = [baseClass, bare ? `${baseClass}--bare` : '', className]
    .filter(Boolean)
    .join(' ');

  /* Resolve theme-aware colours once per render */
  const resolvedBarColor = barColor || getCSSVar('--color-chart-series-1', '#0E6E8F');
  const textSecondary = getCSSVar('--color-text-secondary', '#303030');
  // Ticks and legend read the caption type token, so a theme's type scale
  // reaches them. recharts sizes text through an SVG attribute, which cannot
  // hold var(), so the resolved number is read at render.
  const textSize = readTokenPx('--font-caption-size', '12px');
  const gridColor = getCSSVar('--color-divider', 'rgba(214, 214, 214, 0.8)');
  const cursorColor = getCSSVar('--color-bg-container-secondary', '#F1F1F1');

  const renderTooltip = useCallback(
    /* eslint-disable-next-line @typescript-eslint/no-explicit-any */
    (props: any) => (
      <ChartTooltip {...props} locale={locale} barColor={resolvedBarColor} dataLabel={dataLabel} />
    ),
    [resolvedBarColor, dataLabel, locale],
  );

  return (
    <div
      {...rest}
      ref={ref}
      className={classes}
      role="figure"
      aria-labelledby={title ? titleId : rest['aria-labelledby']}
      aria-describedby={subtitle ? subtitleId : rest['aria-describedby']}
    >
      {/* Header */}
      {(title || subtitle || summaryItems) && (
        <div className={`${baseClass}__header`}>
          <div className={`${baseClass}__header-text`}>
            {title && <h3 id={titleId} className={`${baseClass}__title`}>{title}</h3>}
            {subtitle && <p id={subtitleId} className={`${baseClass}__subtitle`}>{subtitle}</p>}
          </div>
          {summaryItems && summaryItems.length > 0 && (
            <div className={`${baseClass}__summary`}>
              {summaryItems.map((item, i) => (
                <div key={i} className={`${baseClass}__summary-item`}>
                  <span className={`${baseClass}__summary-label`}>{item.label}</span>
                  <span className={`${baseClass}__summary-value`}>
                    {typeof item.value === 'number' ? formatNumber(item.value, locale) : item.value}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Chart */}
      <div className={`${baseClass}__body`}>
        <ResponsiveContainer width="100%" height={height}>
          <RechartsBarChart data={data} margin={{ top: 8, right: 4, bottom: 0, left: -12 }}>
            <CartesianGrid
              vertical={false}
              stroke={gridColor}
              strokeDasharray=""
            />
            <XAxis
              dataKey={xKey}
              tick={{ fill: textSecondary, fontSize: textSize }}
              tickLine={false}
              axisLine={{ stroke: gridColor }}
            />
            <YAxis
              tickFormatter={formatTick}
              tick={{ fill: textSecondary, fontSize: textSize }}
              tickLine={false}
              axisLine={false}
            />
            <Tooltip
              content={renderTooltip}
              cursor={{ fill: cursorColor, opacity: 0.4 }}
            />
            <Bar
              {...animation}
              className={`${baseClass}__bar`}
              dataKey={yKey}
              fill={resolvedBarColor}
              radius={[3, 3, 0, 0]}
              maxBarSize={32}
            />
          </RechartsBarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
});

BarChart.displayName = 'BarChart';

/* ============================================
   CHART COMPONENT — shared styles
   Wrapper, header, tooltip, and summary stats
   used across all chart types (bar, line, pie…).
   ============================================ */

/* ============================================
   WRAPPER
   ============================================ */

.ds-chart {
  display: flex;
  flex-direction: column;
  gap: var(--gap-500); /* 20px */
  width: 100%;
  padding: var(--padding-500); /* 24px */
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-400); /* 16px */
  background-color: var(--color-bg-container-primary);
}

/* ============================================
   HEADER — title / subtitle + summary stats
   ============================================ */

.ds-chart__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--gap-500);
}

.ds-chart__header-text {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050); /* 4px */
}

.ds-chart__title {
  font-family: var(--font-heading-3-family);
  font-size: var(--font-heading-3-size);
  font-weight: var(--font-heading-3-weight);
  line-height: var(--font-heading-3-line-height);
  letter-spacing: var(--font-heading-3-letter-spacing);
  color: var(--color-text-heading);
}

.ds-chart__subtitle {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-secondary);
}

/* ============================================
   SUMMARY STATS — top-right key values
   ============================================ */

.ds-chart__summary {
  display: flex;
  gap: var(--gap-500);
  flex-shrink: 0;
}

.ds-chart__summary-item {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: var(--gap-050);
  padding: var(--padding-150) var(--padding-400);
  border-inline-start: var(--border-025) solid var(--color-bg-container-border);
}

.ds-chart__summary-label {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-secondary);
}

.ds-chart__summary-value {
  font-family: var(--font-heading-1-family);
  font-size: var(--font-heading-1-size);
  font-weight: var(--font-heading-1-weight);
  line-height: var(--font-heading-1-line-height);
  letter-spacing: var(--font-heading-1-letter-spacing);
  color: var(--color-text-heading);
}

/* ============================================
   BODY — the chart area
   ============================================ */

.ds-chart__body {
  width: 100%;
  /* Anchors the radial centre label overlay. */
  position: relative;
}

/* A bar is a large filled mass, so it takes a wash of its series colour, the
   way an area fill does; thin marks (lines, dots, swatches) keep the full token. */
.ds-chart__bar .recharts-rectangle {
  fill-opacity: 0.45;
}

/* ============================================
   BARE MODE — the chart sits inside another
   panel that supplies the surface, so its own
   card chrome would double-frame it
   ============================================ */

.ds-chart--bare {
  border: none;
  padding: 0;
  background-color: transparent;
}

/* ============================================
   RADIAL CENTRE LABEL — the gauge's headline
   in the donut hole
   ============================================ */

.ds-chart__radial-center {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: var(--gap-050);
  pointer-events: none;
}

.ds-chart__radial-center-value {
  font-family: var(--font-sub-display-family);
  font-size: var(--font-sub-display-size);
  font-weight: var(--font-sub-display-weight);
  line-height: var(--font-sub-display-line-height);
  letter-spacing: var(--font-sub-display-letter-spacing);
  color: var(--color-text-display);
}

.ds-chart__radial-center-sub {
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  line-height: var(--font-caption-line-height);
  color: var(--color-text-secondary);
}

/* ============================================
   CUSTOM TOOLTIP
   ============================================ */

.ds-chart__tooltip {
  padding: var(--padding-200) var(--padding-400);
  background-color: var(--color-bg-glass);
  /* The glass token is deliberately translucent; this blur is what keeps
     the chart's marks readable through the overlay. */
  backdrop-filter: blur(24px);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-200); /* 8px */
  box-shadow: var(--shadow-floating);
}

.ds-chart__tooltip-label {
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  color: var(--color-text-primary);
  margin-bottom: var(--gap-050);
}

.ds-chart__tooltip-row {
  display: flex;
  align-items: center;
  gap: var(--gap-200);
}

.ds-chart__tooltip-dot {
  width: 8px;
  height: 8px;
  border-radius: var(--radius-pill);
  flex-shrink: 0;
}

.ds-chart__tooltip-name {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-secondary);
}

.ds-chart__tooltip-value {
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  color: var(--color-text-primary);
  margin-inline-start: auto;
}

/* ============================================
   RESPONSIVE — stack header on small screens
   ============================================ */

/* ds-allow(breakpoint): the phone step on its other edge (below 600px, not at or below it); aligning it would change this rule at exactly 600px. */
@media (max-width: 599px) {
  .ds-chart {
    padding: var(--padding-400);
  }

  .ds-chart__header {
    flex-direction: column;
  }

  .ds-chart__summary {
    width: 100%;
  }

  .ds-chart__summary-item {
    align-items: flex-start;
    flex: 1;
    border-inline-start: none;
    border-top: var(--border-025) solid var(--color-bg-container-border);
    padding: var(--padding-150) 0;
  }
}

'use client';

import React, { useCallback, useEffect, useId, useRef, useState } from 'react';
import {
  Treemap as RechartsTreemap,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import type { ChartSummaryItem } from './BarChart';
import { getChartSeriesColors } from './palette';
import { useChartAnimation } from './useChartAnimation';
import './Chart.css';
import { useLocale } from '../../behaviors/LocaleProvider';
import { formatNumber } from '../../behaviors/locale';

interface TreemapTooltipPayloadEntry {
  value?: number;
  name?: string;
  payload?: Record<string, unknown>;
  [key: string]: unknown;
}

interface TreemapTooltipProps {
  /** The locale the values are written in. */
  locale: string;
  active?: boolean;
  payload?: TreemapTooltipPayloadEntry[];
  sizeLabel: string;
}

export interface TreemapDataItem {
  /** Display name for the node */
  name: string;
  /** Numeric size — determines rectangle area */
  size: number;
  /** Optional fill colour */
  color?: string;
  /** Nested children for hierarchical data */
  children?: TreemapDataItem[];
  [key: string]: unknown;
}

/** Props owned by Treemap itself; everything else falls through to the root div. */
type TreemapOwnProps = {
  /** The BCP 47 locale the values, tooltips and value axis are written in, such as `de-DE`. Defaults to the nearest LocaleProvider's, else `en-US`. */
  locale?: string;
  /** Hierarchical data — each item needs `name` and `size` (or `children`) */
  data: TreemapDataItem[];
  /** Key used for sizing rectangles */
  dataKey?: string;
  /**
   * Chart title, in the shared chart header; it also names the figure.
   * Note: this replaces the native `title` tooltip attribute, which the chart does not expose.
   */
  title?: string;
  /** Description text below the title */
  subtitle?: string;
  /** Summary stats displayed in the header */
  summaryItems?: ChartSummaryItem[];
  /** Chart area height in pixels */
  height?: number;
  /** Strip the card chrome (border, padding, fill) when the chart sits inside another panel that supplies the surface */
  bare?: boolean;
  /** The tooltip's name for a tile's value. Defaults to "Size". */
  sizeLabel?: string;
  /** Additional CSS classes on the wrapper */
  className?: string;
};

export interface TreemapProps
  extends TreemapOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof TreemapOwnProps | 'children'> {}

function getCSSVar(name: string, fallback: string): string {
  // A var() reference resolves live in SVG paint, so the chart follows a
  // theme switch without re-rendering; the fallback covers SSR markup and
  // token-less consumers.
  return `var(${name}, ${fallback})`;
}

// ── Readable labels ─────────────────────────────────────────────────────────
// A cell's fill is any colour — a series token, or whatever a consumer
// passes — so no single text token reads on all of them. The label picks,
// per cell, whichever of the two opposite-polarity text tokens contrasts
// more with the colour the cell actually paints (text-primary and
// text-on-inverse are dark/light in one theme and light/dark in the other).
// The measurement is client-side; the server markup carries text-primary.

type LabelTone = 'primary' | 'on-inverse';
type Rgb = [number, number, number];

let colorProbe: CanvasRenderingContext2D | null | undefined;

/** Any CSS colour string to sRGB channels, via the canvas normaliser. */
function toRgb(value: string): Rgb | null {
  const input = value.trim();
  if (!input || input === 'none') return null;
  if (colorProbe === undefined) {
    colorProbe = document.createElement('canvas').getContext('2d');
  }
  if (!colorProbe) return null;
  colorProbe.fillStyle = '#000000';
  colorProbe.fillStyle = input;
  const out = String(colorProbe.fillStyle);
  if (out.startsWith('#')) {
    return [1, 3, 5].map((i) => parseInt(out.slice(i, i + 2), 16)) as Rgb;
  }
  const m = out.match(/rgba?\(([^)]+)\)/);
  if (!m) return null;
  const [r, g, b] = m[1].split(/[\s,/]+/).map(Number);
  return [r, g, b];
}

const luminance = ([r, g, b]: Rgb) => {
  const lin = (c: number) => {
    const s = c / 255;
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
};

const contrast = (a: Rgb, b: Rgb) => {
  const [hi, lo] = [luminance(a), luminance(b)].sort((p, q) => q - p);
  return (hi + 0.05) / (lo + 0.05);
};

/** WCAG AA for the labels' size (12px semibold is not "large" text). */
const AA_TEXT = 4.5;

interface LabelStyle {
  tone: LabelTone;
  /**
   * A mid-tone fill can sit below AA with both tokens — near-black and
   * near-white both land around 4.3:1 on a fill near 22% luminance. Then
   * the label wears a halo in the opposite token, so the text reads
   * against its halo rather than the fill.
   */
  halo: boolean;
}

function pickLabelStyle(rect: SVGRectElement): LabelStyle {
  const style = getComputedStyle(rect);
  const fill = toRgb(style.fill);
  const primary = toRgb(style.getPropertyValue('--color-text-primary'));
  const onInverse = toRgb(style.getPropertyValue('--color-text-on-inverse'));
  if (!fill || !primary || !onInverse) return { tone: 'primary', halo: false };
  const primaryRatio = contrast(primary, fill);
  const onInverseRatio = contrast(onInverse, fill);
  const tone = primaryRatio >= onInverseRatio ? 'primary' : 'on-inverse';
  return { tone, halo: Math.max(primaryRatio, onInverseRatio) < AA_TEXT };
}

/**
 * Bumps whenever the root element's theme could have changed — a
 * `data-theme` flip, a `data-brand` preset, or overrides written to its
 * inline style — so every cell re-measures its fill.
 */
function useThemeVersion(): number {
  const [version, setVersion] = useState(0);
  useEffect(() => {
    const observer = new MutationObserver(() => setVersion((v) => v + 1));
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['data-theme', 'data-brand', 'style', 'class'],
    });
    return () => observer.disconnect();
  }, []);
  return version;
}

/* eslint-disable-next-line @typescript-eslint/no-explicit-any */
function TreemapContent(props: any) {
  const { x, y, width, height, name, index, color, themeVersion } = props;
  const rectRef = useRef<SVGRectElement>(null);
  const [label, setLabel] = useState<LabelStyle>({ tone: 'primary', halo: false });

  const seriesColors = getChartSeriesColors();
  const fill = color || seriesColors[index % seriesColors.length];
  const visible = width >= 4 && height >= 4;
  const showLabel = width > 50 && height > 28;

  useEffect(() => {
    if (!showLabel || !rectRef.current) return;
    setLabel(pickLabelStyle(rectRef.current));
  }, [fill, showLabel, themeVersion]);

  if (!visible) return null;

  const primaryText = getCSSVar('--color-text-primary', '#050505');
  const onInverseText = getCSSVar('--color-text-on-inverse', '#F1F1F1');
  const textColor = label.tone === 'primary' ? primaryText : onInverseText;
  const haloColor = label.tone === 'primary' ? onInverseText : primaryText;

  return (
    <g>
      <rect
        ref={rectRef}
        x={x}
        y={y}
        width={width}
        height={height}
        rx={4}
        ry={4}
        style={{ fill, stroke: getCSSVar('--color-bg-container-primary', '#FFFFFF'), strokeWidth: 2 }}
      />
      {showLabel && (
        <text
          x={x + width / 2}
          y={y + height / 2}
          textAnchor="middle"
          dominantBaseline="central"
          style={{
            fill: textColor,
            // The tile label reads as a small title: the caption size at the
            // title tier's weight, both from the type tokens.
            fontSize: 'var(--font-caption-size)',
            fontWeight: 'var(--font-title-body-weight)' as React.CSSProperties['fontWeight'],
            ...(label.halo && {
              stroke: haloColor,
              strokeWidth: 3,
              strokeLinejoin: 'round' as const,
              paintOrder: 'stroke',
            }),
          }}
        >
          {name}
        </text>
      )}
    </g>
  );
}

function TreemapTooltip({ locale, active, payload, sizeLabel }: TreemapTooltipProps) {
  if (!active || !payload?.length) return null;
  const entry = payload[0];

  return (
    <div className="ds-chart__tooltip">
      <div className="ds-chart__tooltip-label">{entry.name}</div>
      <div className="ds-chart__tooltip-row">
        <span className="ds-chart__tooltip-name">{sizeLabel}</span>
        <span className="ds-chart__tooltip-value">
          {(entry.value === undefined ? undefined : formatNumber(entry.value, locale))}
        </span>
      </div>
    </div>
  );
}

/**
 * Treemap chart built on Recharts with design-system tokens.
 * Displays hierarchical data as nested coloured rectangles sized by value.
 */
export const Treemap = React.forwardRef<HTMLDivElement, TreemapProps>(({
  data,
  dataKey = 'size',
  title,
  subtitle,
  summaryItems,
  height = 350,
  bare = false,
  sizeLabel = 'Size',
  className = '',
  locale: localeProp,
  ...rest
}, ref) => {
  const locale = useLocale(localeProp);
  const titleId = useId();
  const subtitleId = useId();
  const animation = useChartAnimation(data);
  const themeVersion = useThemeVersion();
  const baseClass = 'ds-chart';
  const classes = [baseClass, bare ? `${baseClass}--bare` : '', className]
    .filter(Boolean)
    .join(' ');

  const renderTooltip = useCallback(
    /* eslint-disable-next-line @typescript-eslint/no-explicit-any */
    (props: any) => <TreemapTooltip {...props} locale={locale} sizeLabel={sizeLabel} />,
    [sizeLabel, locale],
  );

  return (
    <div
      {...rest}
      ref={ref}
      className={classes}
      role="figure"
      aria-labelledby={title ? titleId : rest['aria-labelledby']}
      aria-describedby={subtitle ? subtitleId : rest['aria-describedby']}
    >
      {(title || subtitle || summaryItems) && (
        <div className={`${baseClass}__header`}>
          <div className={`${baseClass}__header-text`}>
            {title && <h3 id={titleId} className={`${baseClass}__title`}>{title}</h3>}
            {subtitle && <p id={subtitleId} className={`${baseClass}__subtitle`}>{subtitle}</p>}
          </div>
          {summaryItems && summaryItems.length > 0 && (
            <div className={`${baseClass}__summary`}>
              {summaryItems.map((item, i) => (
                <div key={i} className={`${baseClass}__summary-item`}>
                  <span className={`${baseClass}__summary-label`}>{item.label}</span>
                  <span className={`${baseClass}__summary-value`}>
                    {typeof item.value === 'number' ? formatNumber(item.value, locale) : item.value}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      <div className={`${baseClass}__body`}>
        <ResponsiveContainer width="100%" height={height}>
          <RechartsTreemap
            {...animation}
            data={data}
            dataKey={dataKey}
            aspectRatio={4 / 3}
            content={<TreemapContent themeVersion={themeVersion} />}
          >
            <Tooltip content={renderTooltip} />
          </RechartsTreemap>
        </ResponsiveContainer>
      </div>
    </div>
  );
});

Treemap.displayName = 'Treemap';

/**
 * The ordered series palette shared by every multi-series chart.
 * Each entry is a var() reference to the `--color-chart-series-{n}` token,
 * which SVG paint resolves live, so the palette follows the active theme
 * (including a mid-session switch) and any consumer re-theming of the
 * tokens. The fallbacks are the light-theme resolved values, used when a
 * token is missing from the cascade.
 */
const SERIES_FALLBACKS = [
  '#0E6E8F',
  '#06D6A0',
  '#FFD166',
  '#EF476F',
  '#9E47EF',
  '#EF8247',
  '#1E47B0',
];

export function getChartSeriesColors(): string[] {
  return SERIES_FALLBACKS.map(
    (fallback, i) => `var(--color-chart-series-${i + 1}, ${fallback})`,
  );
}

/**
 * A type token's size in pixels, read at render. recharts sizes SVG text
 * through an attribute, which cannot hold var(), so the chart text needs the
 * resolved number: the token's computed value on the document, which follows
 * a theme's type scale. Server markup and a consumer without the token get the
 * fallback, the token's base value (validate-token-references.mjs holds it to
 * the token); recharts draws no text until it has measured on the client.
 */
export function readTokenPx(name: string, fallback: string): number {
  const base = parseFloat(fallback);
  if (typeof window === 'undefined') return base;
  const value = parseFloat(getComputedStyle(document.documentElement).getPropertyValue(name));
  return Number.isFinite(value) && value > 0 ? value : base;
}

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';

/** The animation props every recharts graphical item takes. */
export interface ChartAnimationProps {
  /** recharts' own 'auto' while an entrance is due, so its reduced-motion and SSR guard still applies; false once it has played */
  isAnimationActive: 'auto' | false;
  /** Counts the series that have finished, so the flag drops after the last one */
  onAnimationEnd: () => void;
  /** Set only for a series paced by the wrapper (see `durationMs`) */
  animationDuration?: number;
}

export interface ChartAnimationOptions {
  /**
   * The entrance duration for a series that never reports an end (recharts'
   * Scatter has no end callback). The hook passes it through as
   * `animationDuration` and drops the flag on a timer of twice that length:
   * the timer starts a commit or two before the sweep does, and a late drop
   * costs nothing where an early one would cut the tail.
   */
  durationMs?: number;
}

/**
 * Holds a chart's entrance animation to mount and to new data.
 *
 * recharts keys each series' animation to its computed geometry, and a
 * container resize recomputes that geometry, so every width step of a
 * dragged panel replayed the whole entrance frame by frame. The contract
 * is design.md's: a chart animates on mount and when its data changes,
 * and a resize is a re-layout only.
 *
 * `isAnimationActive` is `'auto'` from mount, or from a change of `data`
 * identity, until every series has reported `onAnimationEnd`, then `false`:
 * a remounted animation step with `isAnimationActive={false}` renders once,
 * straight at its end state. Spread the result onto each series;
 * `seriesCount` is how many carry it, so the flag only drops once the last
 * has finished (a ComboChart's bar ends long before its line). Under
 * reduced motion or in SSR no series ever reports, and the flag stays
 * `'auto'`, which recharts resolves to off either way.
 *
 * The end callback keeps one identity per entrance: recharts restarts the
 * animation when the callback it holds changes, so a fresh one per render
 * would replay what this hook exists to stop.
 */
export function useChartAnimation(
  data: unknown,
  seriesCount = 1,
  { durationMs }: ChartAnimationOptions = {},
): ChartAnimationProps {
  /* Derived during render, so the series that mount with the new data
     already carry 'auto': a flag set from an effect could land a render
     late, after recharts has keyed the new geometry. Each entrance is a
     cycle, and the ends counted against it are only its own. */
  const [seenData, setSeenData] = useState(data);
  const [cycle, setCycle] = useState(0);
  const [ended, setEnded] = useState(0);
  if (seenData !== data) {
    setSeenData(data);
    setCycle((c) => c + 1);
    setEnded(0);
  }

  /* A cancelled entrance never reports, but its last frame can land in the
     gap between the new cycle's commit and the cancel, so an end is counted
     only when it comes from the cycle now on screen. Written in the layout
     phase, ahead of any animation frame. */
  const currentCycle = useRef(cycle);
  useLayoutEffect(() => {
    currentCycle.current = cycle;
  }, [cycle]);

  const onAnimationEnd = useCallback(() => {
    if (currentCycle.current !== cycle) return;
    setEnded((n) => n + 1);
  }, [cycle]);

  /* The timed fallback, armed once per cycle while a duration is set. */
  useEffect(() => {
    if (durationMs == null) return undefined;
    const timer = window.setTimeout(() => setEnded(seriesCount), durationMs * 2);
    return () => window.clearTimeout(timer);
  }, [durationMs, cycle, seriesCount]);

  return {
    isAnimationActive: ended < seriesCount ? 'auto' : false,
    onAnimationEnd,
    ...(durationMs == null ? {} : { animationDuration: durationMs }),
  };
}
